<script setup lang="ts">
import {ref} from 'vue';
import {api,upload,can,type Configuration} from './api';
const props=defineProps<{dirty:boolean;licensed:boolean}>(),emit=defineEmits<{updated:[Configuration]}>();
interface Preview{previewId:string|null;configurationRevision:number;added:number;updated:number;issues:string[];changedTanks:string[];differences:{tankCode:string;field:string;before:string;after:string}[];note:string}
const preview=ref<Preview|null>(null),open=ref(false),busy=ref(false),error=ref(''),confirmed=ref(false),fileName=ref(''),reviewTank=ref('');
async function download(template=false){busy.value=true;error.value='';try{const response=await fetch('/api/tank-configuration/export'+(template?'?template=true':''));if(!response.ok){const data=await response.json();throw Error(data.error||'配置导出失败')}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=template?'储罐配置导入模板.xlsx':'储罐配置.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=String(e)}finally{busy.value=false}}
async function select(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;open.value=true;error.value='';preview.value=null;confirmed.value=false;fileName.value=file.name;busy.value=true;try{if(props.dirty)throw Error('请先保存或重新载入当前待保存配置，再导入Excel');if(file.size>4*1024*1024)throw Error('文件不能超过4MiB');preview.value=await upload('/api/tank-configuration/import-preview',file);reviewTank.value=preview.value?.changedTanks[0]||''}catch(e){error.value=String(e)}finally{busy.value=false}}
async function commit(){if(!preview.value?.previewId)return;busy.value=true;error.value='';try{const saved=await api<Configuration>('/api/tank-configuration/import-commit','POST',{previewId:preview.value.previewId,confirmed:confirmed.value});emit('updated',saved);open.value=false;preview.value=null}catch(e){error.value=String(e);preview.value=null}finally{busy.value=false}}
</script>
<template><div class="configuration-transfer"><div class="inline-actions"><button v-if="can('DataExport')" class="button" :disabled="!licensed||busy||dirty" @click="download()">导出储罐配置</button><button v-if="can('DataExport')" class="button" :disabled="!licensed||busy||dirty" @click="download(true)">下载导入模板</button><label class="button file-picker" :class="{disabled:!licensed||busy||dirty}">导入储罐配置<input type="file" accept=".xlsx" :disabled="!licensed||busy||dirty" aria-label="导入储罐配置文件" @change="select"></label></div><p v-if="error&&!open" class="error-message" role="alert">{{error}}</p></div><div v-if="open" class="modal-backdrop"><section class="modal" role="dialog" aria-label="储罐配置导入预览"><div class="modal-head"><div><h2>储罐配置导入预览</h2><p>{{fileName}}</p></div><button class="button" :disabled="busy" @click="open=false">关闭</button></div><div class="modal-body"><p v-if="busy">正在处理…</p><p v-if="error" class="error-message" role="alert">{{error}}</p><template v-if="preview"><p>当前配置版本 {{preview.configurationRevision}} · 新增 {{preview.added}} 罐 · 已有 {{preview.updated}} 罐</p><p class="help">{{preview.note}} 预览10分钟内有效，其他用户修改配置后须重新预览。</p><div v-if="preview.issues.length" class="import-issues"><h3>请修正后重新上传</h3><p v-for="(issue,n) in preview.issues" :key="n" class="error-message">{{issue}}</p></div><template v-else><h3>本次储罐</h3><p class="import-tank-codes">{{preview.changedTanks.join('、')}}</p><template v-if="preview.differences.length"><label class="config-field">查看储罐变更<select v-model="reviewTank" aria-label="查看储罐导入变更"><option v-for="code in preview.changedTanks" :key="code" :value="code">{{code}}</option></select></label><div class="table-wrap import-differences"><table><thead><tr><th>字段</th><th>原值</th><th>导入值</th></tr></thead><tbody><tr v-for="(difference,n) in preview.differences.filter(d=>d.tankCode===reviewTank)" :key="n"><td>{{difference.field}}</td><td>{{difference.before}}</td><td>{{difference.after}}</td></tr><tr v-if="!preview.differences.some(d=>d.tankCode===reviewTank)"><td colspan="3">本罐没有字段变化</td></tr></tbody></table></div></template><p v-else class="help">本次导入各字段与当前配置一致。</p><label class="checkbox"><input v-model="confirmed" type="checkbox">已核对储罐、通讯绑定、报警、计量及允许操作，确认保存本次配置</label><button class="button primary" :disabled="busy||!confirmed" @click="commit">确认导入并保存</button></template></template></div></section></div></template>
